BEGIN;SET ROLE postgres;SELECT set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);UPDATE sigo_correccion_inicial.configuracion SET habilitada=true;DO $g$ DECLARE r record;BEGIN FOR r IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('corregir_unidad_inicial_sigo','previsualizar_correccion_unidad_inicial_sigo','guardar_producto_medida_revision_sigo','listar_revisiones_unidad_producto_sigo') LOOP EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',r.oid::regprocedure);END LOOP;END $g$;SET ROLE authenticated;UPDATE productos SET unidad_revision=1 WHERE id='30000000-0000-0000-0000-000000000004';ROLLBACK;